const body = $input.item.json.body || $input.item.json;
const companyId = body.companyId;
const companyName = body.companyName || 'Target Enterprise';
const rawWebsite = (body.website || '').trim();
const industry = body.industry || 'Commercial Enterprise';
const location = body.location || 'UAE';

if (!companyId) {
  throw new Error('MISSION CONTROL FAULT: companyId UUID is required in telemetry ingestion.');
}

const missionId = 'NASA-LIO-' + Date.now().toString(36).toUpperCase();
const orbitalEpoch = new Date().toISOString();

return {
  json: {
    missionId,
    orbitalEpoch,
    companyId,
    companyName,
    rawWebsite,
    industry,
    location,
    telemetryLog: [
      `[${orbitalEpoch}] ORBITAL INGESTION ESTABLISHED for ${companyName} (${companyId})`
    ]
  }
};

const prev = $input.item.json;
const hasUrl = Boolean(prev.rawWebsite && prev.rawWebsite.length > 2);
const telemetryLog = [...(prev.telemetryLog || [])];
telemetryLog.push(`[${new Date().toISOString()}] FLIGHT_LOG: Target endpoint state: ${hasUrl ? 'ASSIGNED (' + prev.rawWebsite + ')' : 'UNASSIGNED (NO_DOMAIN)'}`);

return {
  json: {
    ...prev,
    hasUrl,
    telemetryLog,
    flightStatus: 'PRE_PROBE_INITIALIZED'
  }
};

const prev = $input.item.json;
let targetUrl = '';
if (prev.rawWebsite) {
  targetUrl = prev.rawWebsite.startsWith('http') ? prev.rawWebsite : ('https://' + prev.rawWebsite);
}
const telemetryLog = [...(prev.telemetryLog || [])];
telemetryLog.push(`[${new Date().toISOString()}] PROTOCOL_FORMATTER: Target orbital probe resolved to: ${targetUrl || 'NONE'}`);

return {
  json: {
    ...prev,
    targetUrl,
    telemetryLog,
    probeConfig: {
      timeoutMs: 6000,
      userAgent: 'NASA-LeadIntel-Probe/4.2 (Spaceborne Autonomous Inspector)'
    }
  }
};

const httpData = $input.item.json || {};
const leadData = $('🌐 Orbital DNS & Protocol Formatter').first().json;
const telemetryLog = [...(leadData.telemetryLog || [])];

const hasUrl = leadData.hasUrl;
const statusCode = httpData.statusCode;
const isError = Boolean(httpData.error || (hasUrl && (statusCode === undefined || statusCode >= 400)));
const isOnline = hasUrl && !isError;
const rawHtml = typeof httpData.data === 'string' ? httpData.data : (typeof httpData === 'string' ? httpData : '');
const payloadBytes = rawHtml.length;
const payloadKb = (payloadBytes / 1024).toFixed(2);

telemetryLog.push(`[${new Date().toISOString()}] TACHOMETER: HTTP Probe status=${statusCode || (isOnline ? 200 : 'ERR')}, Payload=${payloadKb} KB, Online=${isOnline}`);

return {
  json: {
    ...leadData,
    statusCode: statusCode || (isOnline ? 200 : 0),
    isOnline,
    payloadKb,
    rawHtml,
    telemetryLog
  }
};

const prev = $input.item.json;
const hasHttps = (prev.targetUrl || '').startsWith('https://');
const sslObservations = [];
let sslScoreDeduction = 0;

if (!prev.hasUrl) {
  sslObservations.push('No website domain exists to evaluate SSL encryption.');
} else if (!prev.isOnline) {
  sslObservations.push('Target server unreachable; TLS handshake failed or timed out.');
  sslScoreDeduction = 15;
} else if (!hasHttps) {
  sslObservations.push('CRITICAL: Target server serves plain HTTP; zero SSL encryption active.');
  sslScoreDeduction = 20;
} else {
  sslObservations.push('VERIFIED: Active SSL encryption and HTTPS protocol enforced.');
}

return {
  json: {
    ...prev,
    sslAudit: {
      hasHttps,
      sslScoreDeduction,
      sslObservations,
      cipherGrade: hasHttps ? 'A+' : 'F'
    }
  }
};

const prev = $input.item.json;
const html = prev.rawHtml || '';
const hasMobile = /<meta[^>]*name=["']viewport["'][^>]*content=["'][^"']*width=device-width/i.test(html);
const hasAppleTouchIcon = /rel=["']apple-touch-icon["']/i.test(html);
const viewportObservations = [];
let mobileScoreDeduction = 0;

if (prev.isOnline) {
  if (!hasMobile) {
    viewportObservations.push('CRITICAL: Missing responsive mobile viewport meta tag.');
    mobileScoreDeduction = 25;
  } else {
    viewportObservations.push('VERIFIED: Responsive mobile viewport configured with device-width.');
  }
}

return {
  json: {
    ...prev,
    viewportAudit: {
      hasMobile,
      hasAppleTouchIcon,
      mobileScoreDeduction,
      viewportObservations
    }
  }
};

const d = $input.item.json;
return {
  json: {
    satelliteBeacon: 'SATELLITE-ALPHA-THREAT',
    missionId: d.missionId,
    cipherGrade: d.sslAudit?.cipherGrade,
    viewportConfigured: d.viewportAudit?.hasMobile,
    threatLevel: !d.sslAudit?.hasHttps || !d.viewportAudit?.hasMobile ? 'ELEVATED' : 'NOMINAL',
    timestamp: new Date().toISOString()
  }
};

const d = $input.item.json;
return {
  json: {
    groundStation: 'DUBAI-SPACE-GATEWAY-1',
    missionId: d.missionId,
    bandwidthCapturedKb: d.payloadKb,
    signalHealth: d.isOnline ? 'NOMINAL' : 'DEGRADED',
    timestamp: new Date().toISOString()
  }
};

const prev = $input.item.json;
const html = prev.rawHtml || '';

const cms = [];
if (/wp-content|wordpress/i.test(html)) cms.push('WordPress');
if (/shopify/i.test(html)) cms.push('Shopify');
if (/webflow/i.test(html)) cms.push('Webflow');
if (/wix/i.test(html)) cms.push('Wix');
if (/squarespace/i.test(html)) cms.push('Squarespace');

const frameworks = [];
if (/_next/i.test(html)) frameworks.push('Next.js');
if (/react/i.test(html)) frameworks.push('React');
if (/vue/i.test(html)) frameworks.push('Vue');
if (/angular/i.test(html)) frameworks.push('Angular');

const analytics = [];
if (/googletagmanager|google-analytics|gtag/i.test(html)) analytics.push('Google Analytics (GA4)');
if (/connect\.facebook\.net/i.test(html)) analytics.push('Meta Pixel');
if (/hotjar/i.test(html)) analytics.push('Hotjar');

const chatWidgets = [];
if (/(wa\.me|api\.whatsapp\.com\/send)/i.test(html)) chatWidgets.push('WhatsApp Direct Link');
if (/intercom/i.test(html)) chatWidgets.push('Intercom');
if (/crisp/i.test(html)) chatWidgets.push('Crisp');
if (/tidio/i.test(html)) chatWidgets.push('Tidio');
if (/tawk\.to/i.test(html)) chatWidgets.push('Tawk.to');

const techStack = [...cms, ...frameworks, ...analytics, ...chatWidgets];

return {
  json: {
    ...prev,
    techAudit: {
      cms,
      frameworks,
      analytics,
      chatWidgets,
      techStack
    }
  }
};

const d = $input.item.json;
return {
  json: {
    satelliteBeacon: 'SATELLITE-BETA-TRUST',
    missionId: d.missionId,
    techStackDetectedCount: (d.techAudit?.techStack || []).length,
    cmsFound: (d.techAudit?.cms || []).join(', ') || 'Custom Engine',
    frameworksFound: (d.techAudit?.frameworks || []).join(', ') || 'Vanilla DOM',
    timestamp: new Date().toISOString()
  }
};

const d = $input.item.json;
return {
  json: {
    groundStation: 'HOUSTON-DEEP-SPACE-NET',
    missionId: d.missionId,
    analyticsCount: (d.techAudit?.analytics || []).length,
    chatEngines: (d.techAudit?.chatWidgets || []).join(', ') || 'None',
    timestamp: new Date().toISOString()
  }
};

const prev = $input.item.json;
const html = prev.rawHtml || '';

const hasForm = /<form/i.test(html) && /(contact|message|submit|enquiry|email|name)/i.test(html);
const hasBooking = /(calendly\.com|booksy\.com|fresha\.com|book-now|schedule|appointment)/i.test(html);
const hasPortfolio = /(portfolio|projects|gallery|our-work|works|case-studies)/i.test(html);
const hasWhatsapp = /(wa\.me|api\.whatsapp\.com\/send)/i.test(html);

let conversionDeduction = 0;
if (prev.isOnline) {
  if (!hasForm && !hasBooking) conversionDeduction += 20;
  if (!hasPortfolio) conversionDeduction += 15;
}

return {
  json: {
    ...prev,
    conversionAudit: {
      hasForm,
      hasBooking,
      hasPortfolio,
      hasWhatsapp,
      conversionDeduction
    }
  }
};

const d = $input.item.json;
return {
  json: {
    satelliteBeacon: 'SATELLITE-GAMMA-CONVERSION',
    missionId: d.missionId,
    hasInboundForm: d.conversionAudit?.hasForm,
    hasBookingEngine: d.conversionAudit?.hasBooking,
    hasPortfolioEvidence: d.conversionAudit?.hasPortfolio,
    conversionFrictionPenalty: d.conversionAudit?.conversionDeduction,
    timestamp: new Date().toISOString()
  }
};

const d = $input.item.json;
return {
  json: {
    groundStation: 'KENNEDY-TELEMETRY-RADAR',
    missionId: d.missionId,
    whatsappDetected: d.conversionAudit?.hasWhatsapp,
    automatedBotLayer: false,
    opportunityVerdict: d.conversionAudit?.hasWhatsapp ? 'HIGH_INTENT_WHATSAPP_BOT_CANDIDATE' : 'STANDARD_CHANNEL',
    timestamp: new Date().toISOString()
  }
};

const prev = $input.item.json;
const hasUrl = prev.hasUrl;
const isOnline = prev.isOnline;
const ssl = prev.sslAudit || {};
const vp = prev.viewportAudit || {};
const tech = prev.techAudit || {};
const conv = prev.conversionAudit || {};

const detectedProblems = [];
const evidenceMatrix = [];
let websiteScore = 100;

if (!hasUrl) {
  websiteScore = 0;
  detectedProblems.push('No dedicated verified website URL');
  evidenceMatrix.push({
    observation: 'No registered web presence detected.',
    evidence: 'Lead record has no verified website endpoint.',
    impact: 'Losing high-intent UAE commercial search traffic to competitors.',
    recommendedSolution: 'Build a modern greenfield business website.',
    confidence: 95,
    truthTier: 'VERIFIED',
    category: 'PRESENCE'
  });
} else if (!isOnline) {
  websiteScore = 15;
  detectedProblems.push('Website offline or unreachable');
  evidenceMatrix.push({
    observation: 'Website server is unreachable or returned error.',
    evidence: `HTTP request failed (${prev.statusCode || 'Offline'}).`,
    impact: 'Commercial clients encounter offline errors, damaging reputation.',
    recommendedSolution: 'Restore server uptime and deploy cloud hosting.',
    confidence: 90,
    truthTier: 'VERIFIED',
    category: 'UPTIME'
  });
} else {
  if (!ssl.hasHttps) {
    detectedProblems.push('Missing SSL encryption (Plain HTTP in use)');
    websiteScore -= 20;
    evidenceMatrix.push({
      observation: 'Website lacks SSL encryption.',
      evidence: 'Domain loads over insecure HTTP.',
      impact: 'Triggers browser security warnings, destroying trust.',
      recommendedSolution: 'Configure SSL certificate and enforce HTTPS.',
      confidence: 100,
      truthTier: 'VERIFIED',
      category: 'SECURITY'
    });
  }
  if (!vp.hasMobile) {
    detectedProblems.push('No responsive mobile viewport detected');
    websiteScore -= 25;
    evidenceMatrix.push({
      observation: 'Mobile viewport meta tag is missing.',
      evidence: 'HTML lacks responsive viewport tag.',
      impact: 'High bounce rate for UAE mobile visitors.',
      recommendedSolution: 'Rebuild with mobile-first responsive architecture.',
      confidence: 100,
      truthTier: 'VERIFIED',
      category: 'MOBILE'
    });
  }
  if (!conv.hasForm && !conv.hasBooking) {
    detectedProblems.push('No direct enquiry or booking mechanism on primary landing');
    websiteScore -= 20;
    evidenceMatrix.push({
      observation: 'No direct enquiry form or booking flow detected.',
      evidence: 'No <form> or scheduling widget found.',
      impact: 'Interested buyers encounter friction trying to reach sales.',
      recommendedSolution: 'Implement high-converting lead capture funnels.',
      confidence: 95,
      truthTier: 'VERIFIED',
      category: 'CONVERSION'
    });
  }
  if (!conv.hasPortfolio) {
    detectedProblems.push('Project portfolio is difficult to discover');
    websiteScore -= 15;
    evidenceMatrix.push({
      observation: 'Completed projects portfolio is difficult to discover.',
      evidence: 'No dedicated portfolio/project navigation link found.',
      impact: 'High-ticket buyers cannot verify previous craftsmanship.',
      recommendedSolution: 'Deploy a high-resolution project portfolio showcase.',
      confidence: 88,
      truthTier: 'INFERRED',
      category: 'PORTFOLIO'
    });
  }
  if (conv.hasWhatsapp && (tech.chatWidgets || []).length === 1) {
    evidenceMatrix.push({
      observation: 'Business promotes WhatsApp but lacks automated 24/7 qualification.',
      evidence: 'Direct WhatsApp link detected without automated bot layer.',
      impact: 'Delayed responses during off-hours risk losing hot prospects.',
      recommendedSolution: 'Deploy 24/7 AI WhatsApp Qualification Bot.',
      confidence: 90,
      truthTier: 'INFERRED',
      category: 'AI_AUTOMATION'
    });
  }
  websiteScore = Math.max(20, Math.min(100, websiteScore));
}

return {
  json: {
    ...prev,
    websiteStatus: !hasUrl ? 'NO_WEBSITE' : (isOnline ? 'ONLINE' : 'OFFLINE'),
    websiteScore,
    detectedProblems,
    evidenceMatrix,
    digitalPresence: {
      cms: tech.cms || [],
      frameworks: tech.frameworks || [],
      analytics: tech.analytics || [],
      chatWidgets: tech.chatWidgets || [],
      hasWhatsapp: Boolean(conv.hasWhatsapp),
      hasHttps: Boolean(ssl.hasHttps),
      hasMobileViewport: Boolean(vp.hasMobile),
      hasContactForm: Boolean(conv.hasForm),
      hasBooking: Boolean(conv.hasBooking),
      hasPortfolio: Boolean(conv.hasPortfolio)
    }
  }
};

const d = $input.item.json;
return {
  json: {
    satelliteBeacon: 'SATELLITE-DELTA-LEDGER',
    missionId: d.missionId,
    fusedScore: d.websiteScore,
    problemsIdentified: d.detectedProblems.length,
    evidenceEntriesCount: d.evidenceMatrix.length,
    timestamp: new Date().toISOString()
  }
};

const d = $input.item.json;
return {
  json: {
    flightBlackBoxId: 'BB-' + d.missionId,
    recordedAt: new Date().toISOString(),
    companyId: d.companyId,
    websiteStatus: d.websiteStatus,
    healthScore: d.websiteScore,
    status: 'TELEMETRY_COMMITTED_TO_ORBITAL_RECORDS'
  }
};

const d = $input.item.json;
let confidenceScore = 85;
if (d.websiteStatus === 'NO_WEBSITE' || !d.sslAudit?.hasHttps) confidenceScore = 95;
else if (d.viewportAudit?.hasMobile) confidenceScore = 90;

return {
  json: {
    ...d,
    confidenceScore,
    computedHealthGrade: d.websiteScore >= 80 ? 'OPTIMAL' : (d.websiteScore >= 50 ? 'SUB_OPTIMAL' : 'CRITICAL_DEGRADATION')
  }
};

const d = $input.item.json;
const industry = (d.industry || '').toLowerCase();
const hasMobile = d.digitalPresence?.hasMobileViewport;
const hasHttps = d.digitalPresence?.hasHttps;
const hasWhatsapp = d.digitalPresence?.hasWhatsapp;
const hasPortfolio = d.digitalPresence?.hasPortfolio;

let opportunityScore = 70;
let confidenceScore = d.confidenceScore || 80;
let recommendedServiceCode = 'PREMIUM_WEBSITE_REDESIGN';
let recommendedServiceName = 'Premium Website Redesign & Conversion Architecture';
let primaryPainPoint = '';
let reasoning = '';
let potentialImpact = '';
let reasonToContact = '';
let suggestedOffer = '';
let expectedBusinessBenefit = '';
let claimType = 'ESTIMATE';
let pitchAngle = '';
let estimatedBudgetMin = 35000;
let estimatedBudgetMax = 75000;
let recommendedChannel = 'EMAIL';
const evidenceSummary = [];

if (d.websiteStatus === 'NO_WEBSITE' || d.websiteStatus === 'OFFLINE') {
  opportunityScore = 92;
  confidenceScore = 95;
  recommendedServiceCode = 'NEW_HIGH_CONVERTING_WEBSITE';
  recommendedServiceName = 'New High-Converting Business Website & Digital Presence';
