  suggestedOffer = `Custom Greenfield Digital Presence & Portfolio for ${d.companyName}`;
  expectedBusinessBenefit = 'Create a clearer inbound path for potential clients searching for your services and establish direct digital credibility.';
  claimType = 'INFERRED_INSIGHT';
  pitchAngle = 'Direct ownership of digital client acquisition channel without relying solely on social media';
  estimatedBudgetMin = 28000;
  estimatedBudgetMax = 60000;
