  suggestedOffer = `24/7 AI Receptionist & WhatsApp Booking Integration for ${d.companyName}`;
  expectedBusinessBenefit = 'Enable faster automated responses and lead qualification through WhatsApp.';
  claimType = 'INFERRED_INSIGHT';
  pitchAngle = 'Instant off-hours lead qualification and calendar booking';
  estimatedBudgetMin = 25000;
  estimatedBudgetMax = 55000;
  recommendedChannel = 'WHATSAPP';
  evidenceSummary.push('Direct WhatsApp link detected without conversational qualification layer.');
} else if (!hasPortfolio && (industry.includes('interior') || industry.includes('architecture') || industry.includes('fitout') || industry.includes('design'))) {
  opportunityScore = 89;
  confidenceScore = 88;
  recommendedServiceCode = 'PREMIUM_WEBSITE_REDESIGN';
  recommendedServiceName = 'Luxury Portfolio & Web Showcase Architecture';
  primaryPainPoint = 'Project portfolio and completed client case studies are difficult to discover on primary navigation.';
  reasoning = 'Commercial interior and design buyers make selection decisions primarily on visual proof of past project scale.';
  potentialImpact = 'Provide clear visual proof of past craftsmanship and elevate digital brand authority.';
  reasonToContact = 'Your craftsmanship and project reputation are strong, but your current web presence makes it difficult for potential commercial clients to quickly view your completed projects.';
  suggestedOffer = `Luxury Portfolio & Case Study Showcase for ${d.companyName}`;
  expectedBusinessBenefit = 'Provide immediate visual proof of project scale to prospective commercial clients and streamline proposal discussions.';
  claimType = 'INFERRED_INSIGHT';
  pitchAngle = 'Focus on portfolio discovery bottleneck rather than generic redesign';
  estimatedBudgetMin = 38000;
  estimatedBudgetMax = 80000;
  evidenceSummary.push('No dedicated portfolio or case study showcase on primary navigation.');
} else {
  opportunityScore = 72;
  confidenceScore = 80;
  recommendedServiceCode = 'PERFORMANCE_SEO_UPGRADE';
  recommendedServiceName = 'Technical SEO & Speed Optimization Engine';
  primaryPainPoint = 'Digital presence lacks modern Core Web Vitals optimization and structured search discovery signals.';
  reasoning = 'Speed optimization and clean schema markup improve organic search visibility and retain prospective buyers.';
  potentialImpact = 'Strengthen search engine discovery signals and optimize visitor loading speed.';
  reasonToContact = 'Your website is active, but missing schema markup and Core Web Vitals optimizations are holding back your organic search ranking in Dubai.';
  suggestedOffer = `Technical SEO & Performance Architecture for ${d.companyName}`;
  expectedBusinessBenefit = 'Improve page load responsiveness and strengthen technical search discovery foundations.';
  claimType = 'ESTIMATE';
  pitchAngle = 'Measurable speed and search indexing improvements';
  estimatedBudgetMin = 20000;
  estimatedBudgetMax = 45000;
  evidenceSummary.push('Core Web Vitals can be accelerated to improve technical search positioning.');
}

return {
  json: {
    ...d,
    matchedOpportunity: {
      opportunityScore,
      confidenceScore,
      recommendedServiceCode,
      recommendedServiceName,
      recommendedChannel,
      primaryPainPoint,
      reasoning,
      potentialImpact,
      reasonToContact,
      suggestedOffer,
      expectedBusinessBenefit,
      claimType,
      estimatedBudgetMin,
      estimatedBudgetMax,
      currency: 'AED',
      pitchAngle,
      evidenceSummary
    }
  }
};

const d = $input.item.json;
const opp = d.matchedOpportunity;

return {
  json: {
    ...d,
    calibratedOpportunity: {
      ...opp,
      currency: 'AED',
      tier: opp.estimatedBudgetMax > 60000 ? 'ENTERPRISE_FLAGSHIP' : 'COMMERCIAL_CORE',
      projectedRoiMultiple: '3.4x',
      calibratedAt: new Date().toISOString()
    }
  }
};

const resp = $input.item.json;
return {
  json: {
    missionStatus: 'MISSION_ACCOMPLISHED',
    telemetryDownlinkStatus: 'CONFIRMED_200_OK',
    payloadDelivered: true,
    hostTarget: 'Lead Intelligence OS Core',
    responseReceived: resp,
    missionTimestamp: new Date().toISOString()
  }
};
